const targets=await (await fetch('http://127.0.0.1:9222/json')).json();
const page=targets.find(x=>x.type==='page');
const ws=new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject;});
let id=0;const pending=new Map();const logs=[];
ws.onmessage=event=>{const message=JSON.parse(event.data);if(message.id&&pending.has(message.id)){pending.get(message.id)(message);pending.delete(message.id);}if(message.method==='Runtime.exceptionThrown')logs.push(message.params.exceptionDetails.text);if(message.method==='Log.entryAdded'&&message.params.entry.level==='error')logs.push(message.params.entry.text);};
function call(method,params={}){return new Promise(resolve=>{const requestId=++id;pending.set(requestId,resolve);ws.send(JSON.stringify({id:requestId,method,params}));});}
await call('Runtime.enable');await call('Log.enable');await call('Page.enable');
async function evaluate(expression){const result=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(result.error)throw new Error(JSON.stringify(result.error));return result.result?.result?.value;}
await evaluate("document.querySelector('#play-btn').click()");
await evaluate("document.querySelector('#continue-btn').click()");
await evaluate("document.querySelector('#fight-btn').click()");
await new Promise(resolve=>setTimeout(resolve,3000));
const shot=await call('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});
await import('node:fs/promises').then(fs=>fs.writeFile('/tmp/opencode/sansad-fight.png',Buffer.from(shot.result.data,'base64')));
console.log(JSON.stringify({errors:logs,screen:await evaluate("document.querySelector('#fight-ui').className"),timer:await evaluate("document.querySelector('#timer').textContent")}));
ws.close();
